import { actions, afterMount, connect, kea, MakeLogicType, path, reducers, selectors } from 'kea'

import { userLogic } from 'scenes/userLogic'

import type { UserType } from '~/types'

import { AdventRewards, drawAdventRewards } from '../adventDraw'
import { AdventProgress, EMPTY_ADVENT_PROGRESS } from '../adventGraph'
import { cleanProgressByUser, storedProgressByUser } from '../adventProgressStorage'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adventEntryProgressLogicValues {
    user: UserType | null // userLogic
    progress: AdventProgress | null
    progressByUser: Record<string, AdventProgress> | null
    rewards: AdventRewards | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adventEntryProgressLogicActions {
    readStoredProgress: () => {
        stored: unknown
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface adventEntryProgressLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        progress: (
            progressByUser: Record<string, AdventProgress> | null,
            user: UserType | null
        ) => AdventProgress | null
        rewards: (user: UserType | null) => AdventRewards | null
    }
}

export type adventEntryProgressLogicType = MakeLogicType<
    adventEntryProgressLogicValues,
    adventEntryProgressLogicActions,
    Record<string, any>,
    adventEntryProgressLogicMeta
>

export const adventEntryProgressLogic = kea<adventEntryProgressLogicType>([
    path(['products', 'workflows', 'frontend', 'AdventCalendar', 'entry', 'adventEntryProgressLogic']),
    connect(() => ({
        values: [userLogic, ['user']],
    })),
    actions({
        readStoredProgress: () => ({ stored: storedProgressByUser() }),
    }),
    reducers({
        progressByUser: [
            null as Record<string, AdventProgress> | null,
            {
                readStoredProgress: (_, { stored }) => cleanProgressByUser(stored),
            },
        ],
    }),
    selectors({
        progress: [
            (s) => [s.progressByUser, s.user],
            (
                progressByUser: adventEntryProgressLogicValues['progressByUser'],
                user: adventEntryProgressLogicValues['user']
            ): AdventProgress | null =>
                progressByUser && user ? (progressByUser[user.uuid] ?? EMPTY_ADVENT_PROGRESS) : null,
        ],
        rewards: [
            (s) => [s.user],
            (user: adventEntryProgressLogicValues['user']): AdventRewards | null =>
                user ? drawAdventRewards(user.uuid) : null,
        ],
    }),
    afterMount(({ actions }) => {
        actions.readStoredProgress()
    }),
])
